function toggleSidebar(){const sidebar=document.getElementById('sidebar');const overlay=document.getElementById('sidebarOverlay');if(!sidebar)return;const isOpen=sidebar.classList.contains('open');if(isOpen){sidebar.classList.remove('open');if(overlay)overlay.classList.remove('open');}else{sidebar.classList.add('open');if(overlay)overlay.classList.add('open');}}document.addEventListener('DOMContentLoaded',function(){const overlay=document.getElementById('sidebarOverlay');if(overlay){overlay.addEventListener('click',toggleSidebar);}});function toggleSection(headerEl){const section=headerEl.parentElement;const items=section.querySelector('.sidebar-items');if(!items)return;const isCollapsed=section.classList.contains('collapsed');if(isCollapsed){section.classList.remove('collapsed');items.style.display='';headerEl.classList.remove('collapsed');}else{section.classList.add('collapsed');items.style.display='none';headerEl.classList.add('collapsed');}}document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.sidebar-section-title').forEach(function(title){if(!title.hasClickListener){title.hasClickListener=true;title.style.cursor='pointer';title.addEventListener('click',function(){toggleSection(this);});}});});function toggleQA(element){const qaItem=element.closest('.qa-item');if(qaItem){qaItem.classList.toggle('expanded');}}document.addEventListener('DOMContentLoaded',function(){setTimeout(function(){document.querySelectorAll('.stat-card,.quick-entry a,.card').forEach(function(el,i){el.style.animationDelay=(i*0.1)+'s';});},100);});

const searchIndex=[{"type": "book", "title": "走向靜默，如你本來 (Be As You Are)", "url": "/zh-TW/books/be-as-you-are.html", "excerpt": "大衛·高德曼編著，馬雜湊最核心的問答精選與入門指南"}, {"type": "book", "title": "寶鑽集 (Gems from Bhagavan)", "url": "/zh-TW/books/gems.html", "excerpt": "馬雜湊語錄精華，每一則都如寶石般珍貴"}, {"type": "book", "title": "對談錄 (Talks with Sri Ramana Maharshi)", "url": "/zh-TW/books/talks.html", "excerpt": "與馬雜湊的對話記錄，涵蓋修行生活的方方面面"}, {"type": "book", "title": "回到你心中 (Back to the Heart)", "url": "/zh-TW/books/back-to-heart.html", "excerpt": "回到真我本源的心法指引"}, {"type": "book", "title": "日日與彼 (Day by Day with Bhagavan)", "url": "/zh-TW/books/day-by-day.html", "excerpt": "弟子記錄的馬雜湊每日教示"}, {"type": "book", "title": "面對面 (Face to Face)", "url": "/zh-TW/books/face-to-face.html", "excerpt": "馬雜湊與求道者的對話實錄"}, {"type": "book", "title": "秘密印度 (A Search in Secret India)", "url": "/zh-TW/books/search-secret-india.html", "excerpt": "保羅·布倫頓的阿魯那佳拉朝聖記錄"}, {"type": "book", "title": "馬雜湊福音 (Maharshi's Gospel)", "url": "/zh-TW/books/maharshi-gospel.html", "excerpt": "馬雜湊回答求道者的核心靈性教導集"}, {"type": "book", "title": "大瑜伽 (Maha Yoga)", "url": "/zh-TW/books/maha-yoga.html", "excerpt": "馬雜湊親自校閱的不二論哲學鉅著"}, {"type": "book", "title": "上師言頌 (Guru Vachaka Kovai)", "url": "/zh-TW/books/guru-vachaka-kovai.html", "excerpt": "詩人ム魯嘎納爾編纂、馬雜湊親校的權威法語總集"}, {"type": "book", "title": "時代中的永恆 (Timeless in Time)", "url": "/zh-TW/books/timeless.html", "excerpt": "馬雜湊生平傳記與教法的現代詮釋"}, {"type": "book", "title": "反思錄 (Reflections)", "url": "/zh-TW/books/reflections.html", "excerpt": "對談錄核心法義的深度參究與反思"}, {"type": "book", "title": "靈性故事 (Spiritual Stories)", "url": "/zh-TW/books/spiritual-stories.html", "excerpt": "馬雜湊常引用的經典靈性故事彙集"}, {"type": "book", "title": "超越愛與恩典 (Surpassing Love and Grace)", "url": "/zh-TW/books/surpassing-love.html", "excerpt": "關於上師之愛與恩典的深刻回憶錄"}, {"type": "book", "title": "桌邊碎語 (Crumbs from His Table)", "url": "/zh-TW/books/crumbs.html", "excerpt": "靜修院日常親承對話記錄"}, {"type": "book", "title": "以言傳意 (Teachings in His Own Words)", "url": "/zh-TW/books/teachings.html", "excerpt": "亞瑟·奧斯本編纂的馬雜湊分類言教"}, {"type": "book", "title": "拉瑪那馬雜湊全集 (Collected Works)", "url": "/zh-TW/books/collected-works.html", "excerpt": "馬雜湊親筆著作《我是誰》《四十頌》等全集"}, {"type": "book", "title": "拉瑪那靜修院來信 (Letters from Sri Ramanasramam)", "url": "/zh-TW/books/letters.html", "excerpt": "蘇里·納伽瑪書信體記錄的靜修院日常與教誨"}, {"type": "concept", "title": "真我 (Atman)", "url": "/zh-TW/concepts/atman.html", "excerpt": "最內在的存在本質，永恆純粹的意識"}, {"type": "concept", "title": "梵 (Brahman)", "url": "/zh-TW/concepts/brahman.html", "excerpt": "宇宙終極實相，無限的存在-意識-喜悅"}, {"type": "concept", "title": "我是誰？ (Who am I?)", "url": "/zh-TW/concepts/whoami.html", "excerpt": "馬雜湊最核心的自我參究法門"}, {"type": "concept", "title": "自我參究 (Atma Vichara)", "url": "/zh-TW/concepts/atma-vichara.html", "excerpt": "向內追溯我念源頭的直接智慧之道"}, {"type": "concept", "title": "心智 (Manas / Citta)", "url": "/zh-TW/concepts/mind.html", "excerpt": "意識的投射與念頭之流"}, {"type": "concept", "title": "自我 / 小我 (Ego / Ahamkara)", "url": "/zh-TW/concepts/ego.html", "excerpt": "虛假的身心身份認同，一切束縛之根"}, {"type": "concept", "title": "我念 (Aham-vritti)", "url": "/zh-TW/concepts/aham-vritti.html", "excerpt": "心智升起的第一念，通往真我的門戶"}, {"type": "concept", "title": "本心 (Hrdayam / Heart)", "url": "/zh-TW/concepts/heart.html", "excerpt": "靈性中心，真我意識的源頭"}, {"type": "concept", "title": "摩耶 (Maya)", "url": "/zh-TW/concepts/maya.html", "excerpt": "幻相與二元顯現的力量"}, {"type": "concept", "title": "解脫 (Moksha / Mukti)", "url": "/zh-TW/concepts/moksha.html", "excerpt": "消融無明錯認後的本來自在"}, {"type": "concept", "title": "恩典 (Grace / Anugraha)", "url": "/zh-TW/concepts/grace.html", "excerpt": "上師的慈悲加持與真我的內在引力"}, {"type": "concept", "title": "業力 (Karma)", "url": "/zh-TW/concepts/karma.html", "excerpt": "行為、因果法則與定業"}, {"type": "concept", "title": "三摩地 (Samadhi)", "url": "/zh-TW/concepts/samadhi.html", "excerpt": "與真我完全合一的意識定境"}, {"type": "concept", "title": "自然三摩地 (Sahaja Samadhi)", "url": "/zh-TW/concepts/sahaja.html", "excerpt": "在日常行動中恆常不失真我的最高覺醒狀態"}, {"type": "concept", "title": "靜默 (Silence / Mouna)", "url": "/zh-TW/concepts/silence.html", "excerpt": "超越語言文字的至高靈性教導"}, {"type": "concept", "title": "臣服 (Surrender / Sharanagati)", "url": "/zh-TW/concepts/surrender.html", "excerpt": "放下小我做者感，徹底歸依真我"}, {"type": "concept", "title": "上師 (Guru)", "url": "/zh-TW/concepts/guru.html", "excerpt": "外在引導與內在牽引合一的靈性導師"}, {"type": "concept", "title": "習氣 (Vasanas)", "url": "/zh-TW/concepts/vasanas.html", "excerpt": "潛藏於心智深處的宿世習性傾向"}, {"type": "concept", "title": "覺知 (Awareness)", "url": "/zh-TW/concepts/awareness.html", "excerpt": "不生不滅、照亮一切經驗的純粹觀照"}, {"type": "concept", "title": "念頭 (Thoughts)", "url": "/zh-TW/concepts/thoughts.html", "excerpt": "以我念為根的一切心智波浪"}, {"type": "concept", "title": "開悟 / 自我了悟 (Self-Realization)", "url": "/zh-TW/concepts/enlightenment.html", "excerpt": "如實認出自己本來就是無瑕的真我"}, {"type": "concept", "title": "輪迴 (Samsara)", "url": "/zh-TW/concepts/samsara.html", "excerpt": "源於無明認同的生死流轉幻象"}, {"type": "concept", "title": "無我 (Anatman)", "url": "/zh-TW/concepts/anatma.html", "excerpt": "非我之物與佛教無我觀的對照"}, {"type": "concept", "title": "法界 (Dharmata)", "url": "/zh-TW/concepts/dharmata.html", "excerpt": "一切現象的究竟本性"}, {"type": "concept", "title": "解脫之道 (Moksha Marga)", "url": "/zh-TW/concepts/moksha-path.html", "excerpt": "參究與臣服兩條核心解脫路徑"}, {"type": "concept", "title": "專一定住 (Nishtha)", "url": "/zh-TW/concepts/nishtha.html", "excerpt": "堅定安住於真我本源"}, {"type": "concept", "title": "不二論 (Advaita)", "url": "/zh-TW/concepts/advaita.html", "excerpt": "實相唯一無二的核心哲學體系"}, {"type": "concept", "title": "極樂 (Ananda)", "url": "/zh-TW/concepts/ananda.html", "excerpt": "真我本自具足的究竟安寧與喜悅"}, {"type": "concept", "title": "禪定 (Dhyana)", "url": "/zh-TW/concepts/dhyana.html", "excerpt": "心意專注與寂靜修持"}, {"type": "concept", "title": "出離 (Vairagya)", "url": "/zh-TW/concepts/vairagya.html", "excerpt": "對虛妄外境的離欲與清明"}, {"type": "concept", "title": "存在-意識-極樂 (Sat-Chit-Ananda)", "url": "/zh-TW/concepts/satchidananda.html", "excerpt": "真我不可分割的三重本質屬性"}, {"type": "person", "title": "室利·拉瑪那·馬雜湊 (Sri Ramana Maharshi)", "url": "/zh-TW/persons/ramana.html", "excerpt": "近現代最偉大的不二論聖哲與阿魯那佳拉上師"}, {"type": "person", "title": "大衛·高德曼 (David Godman)", "url": "/zh-TW/persons/david.html", "excerpt": "《走向靜默，如你本來》編者與靜修院文獻學者"}, {"type": "person", "title": "韋卡羅達·南達 (Venkataramana)", "url": "/zh-TW/persons/venkataramana.html", "excerpt": "馬雜湊生平重要歷史人物與傳承見證"}, {"type": "method", "title": "參究「我是誰」", "url": "/zh-TW/methods/index.html#whoami", "excerpt": "馬雜湊最核心的直接修行法門"}, {"type": "method", "title": "臣服上師與真我", "url": "/zh-TW/methods/index.html#surrender", "excerpt": "將自我與重擔徹底交託給至高力量"}, {"type": "method", "title": "唸誦咒語 (Japa)", "url": "/zh-TW/methods/index.html#japa", "excerpt": "透過持續持誦收攝散亂心智"}, {"type": "method", "title": "靜默安住 (Mouna)", "url": "/zh-TW/methods/index.html#silence", "excerpt": "融入無念之源的內在靜默"}, {"type": "qa", "title": "修行問答總庫 (800+則分類精選)", "url": "/zh-TW/qa/index.html", "excerpt": "涵蓋真我、心智、參究、臣服、日常生活修行的完整問答"}];const typeLabels={"book":"書籍","concept":"概念","qa":"問答","person":"人物","method":"方法"};const typeColors={book:'#3b82f6',concept:'#8b5cf6',qa:'#f59e0b',person:'#10b981',method:'#ec4899'};function highlightMatch(text,query){if(!query)return text;const regex=new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`,'gi');return text.replace(regex,'<strong style="color:#fbbf24;">$1</strong>');}function initSearch(){const searchInput=document.getElementById('search-input');const searchResults=document.getElementById('search-results');if(!searchInput||!searchResults)return;const isTW=window.location.pathname.indexOf('/zh-TW/')===0||window.location.pathname==='/zh-TW';function resolveUrl(u){if(!u)return '#';if(isTW&&u.indexOf('/zh-TW/')!==0&&u.indexOf('/')===0)return '/zh-TW'+u;return u;}function runQuery(rawVal){const q=(rawVal||'').trim().toLowerCase();if(!q){searchResults.innerHTML='';searchResults.style.display='none';return;}const matches=searchIndex.filter(item=>item.title.toLowerCase().includes(q)||item.excerpt.toLowerCase().includes(q)||(typeLabels[item.type]&&typeLabels[item.type].toLowerCase().includes(q)));if(matches.length===0){searchResults.innerHTML='<div style="padding:16px;color:#64748b;text-align:center;">未找到結果</div>';}else{searchResults.innerHTML=matches.slice(0,10).map(item=>`<a href="${resolveUrl(item.url)}" style="display:block;padding:12px 16px;border-bottom:1px solid rgba(255,255,255,0.05);text-decoration:none;color:#e2e8f0;"><div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;"><span style="background:${typeColors[item.type]||'#666'};padding:2px 8px;border-radius:4px;font-size:11px;">${typeLabels[item.type]||item.type}</span><span style="font-weight:500;">${highlightMatch(item.title,q)}</span></div><div style="font-size:12px;color:#94a3b8;">${highlightMatch(item.excerpt,q)}</div></a>`).join('');}searchResults.style.display='block';}searchInput.addEventListener('input',function(){runQuery(this.value);});searchInput.addEventListener('blur',function(){setTimeout(()=>{searchResults.style.display='none';},200);});searchInput.addEventListener('focus',function(){if(this.value.trim())runQuery(this.value);});try{const params=new URLSearchParams(window.location.search);const urlQ=params.get('q');if(urlQ&&urlQ.trim()){searchInput.value=urlQ.trim();runQuery(urlQ.trim());}}catch(e){}}document.addEventListener('DOMContentLoaded',initSearch);

(function(){'use strict';class AudioReader{constructor(){this.supported=typeof window!=='undefined'&&'speechSynthesis' in window&&'SpeechSynthesisUtterance' in window;this.synth=this.supported?window.speechSynthesis:null;this.utterance=null;this.voices=[];this.selectedVoice=null;this.rate=1.0;this.isPlaying=false;this.isPaused=false;this.chunks=[];this.currentIndex=0;this.totalWords=0;this.estimatedMinutes=0;this.container=null;this.headerBtnEl=null;this.floatingPlayerEl=null;}shouldEnableTTS(){if(!this.supported)return false;if(document.body&&(document.body.hasAttribute('data-no-tts')||document.body.classList.contains('no-tts')))return false;const loc=window.location;if(loc&&loc.pathname){const path=loc.pathname.toLowerCase().replace(/\/index\.html$/,'/');if(path==='/'||path===''||path==='/zh-tw/'||path==='/zh-tw')return false;const hubPaths=['/books/','/concepts/','/methods/','/qa/','/persons/','/sitemap.html','/graph.html','/zh-tw/books/','/zh-tw/concepts/','/zh-tw/methods/','/zh-tw/qa/','/zh-tw/persons/','/zh-tw/sitemap.html','/zh-tw/graph.html'];if(hubPaths.some(hp=>path.endsWith(hp)||path===hp))return false;if(loc.pathname.toLowerCase().endsWith('index.html'))return false;}if(document.querySelector('.stats-grid')||document.querySelector('.books-grid')||document.querySelector('.category-grid')||document.querySelector('.topic-hub-matrix')||document.querySelector('.graph-container')||document.querySelector('.sitemap-tree'))return false;const topbarTitle=document.querySelector('.topbar-title');if(topbarTitle&&(topbarTitle.textContent.includes('首页')||topbarTitle.textContent.includes('首頁')))return false;this.container=document.querySelector('.content-wrapper');if(!this.container)return false;return true;}init(){if(!this.shouldEnableTTS())return;this.extractChunks();if(this.chunks.length===0||this.totalWords<60){return;}this.estimatedMinutes=Math.max(1,Math.ceil(this.totalWords/250));this.loadVoices();if(typeof speechSynthesis!=='undefined'&&speechSynthesis.onvoiceschanged!==undefined){speechSynthesis.onvoiceschanged=()=>this.loadVoices();}this.renderHeaderButton();this.renderFloatingPlayer();window.addEventListener('beforeunload',()=>this.stop());}loadVoices(){if(!this.synth)return;const allVoices=this.synth.getVoices()||[];this.voices=allVoices.filter(v=>v.lang.includes('zh')||v.lang.includes('ZH')||v.lang.includes('cmn'));if(this.voices.length===0){this.voices=allVoices;}const preferred=this.voices.find(v=>v.name.includes('HsiaoChen')||v.name.includes('YunJhe')||v.name.includes('HanHan')||v.name.includes('Yanting')||v.name.includes('Xiaoxiao')||v.name.includes('Yunxi')||v.name.includes('Natural'));this.selectedVoice=preferred||(this.voices.length>0?this.voices[0]:null);this.updateVoiceSelectOptions();}extractChunks(){this.chunks=[];this.totalWords=0;const elements=this.container.querySelectorAll('h1,h2,h3,h4,p,blockquote,li,.quote-box');elements.forEach(el=>{if(el.closest('.page-nav')||el.closest('.breadcrumb')||el.closest('#tts-header-bar')||el.closest('.tag')||el.closest('.geo-citation-card')){return;}let text=el.innerText||el.textContent||'';text=text.trim();if(text.length>1&&!/^[\s\t\n\r]*$/.test(text)){this.chunks.push({text:text,element:el});this.totalWords+=text.length;}});}renderHeaderButton(){const titleEl=this.container.querySelector('.chapter-title,h1')||this.container.firstElementChild;if(!titleEl)return;const headerBar=document.createElement('div');headerBar.id='tts-header-bar';headerBar.className='tts-header-bar';headerBar.setAttribute('data-nosnippet','');headerBar.setAttribute('aria-hidden','true');headerBar.innerHTML=`<button class="tts-play-btn" id="tts-start-btn"><span class="tts-icon">🎧</span><span class="tts-text">聽這篇文章</span><span class="tts-meta">· 約 ${this.estimatedMinutes}分鐘</span></button>`;if(titleEl.nextSibling){titleEl.parentNode.insertBefore(headerBar,titleEl.nextSibling);}else{titleEl.parentNode.appendChild(headerBar);}const startBtn=headerBar.querySelector('#tts-start-btn');startBtn.addEventListener('click',()=>{if(this.isPlaying){if(this.isPaused){this.resume();}else{this.pause();}}else{this.playFrom(0);}});}renderFloatingPlayer(){const floating=document.createElement('div');floating.id='tts-floating-player';floating.className='tts-floating-player tts-hidden';floating.setAttribute('data-nosnippet','');floating.setAttribute('aria-hidden','true');floating.innerHTML=`<div class="tts-player-inner"><div class="tts-info"><span class="tts-badge">🎧 音訊朗讀</span><span class="tts-current-text" id="tts-status-text">準備就緒</span></div><div class="tts-controls"><button class="tts-ctrl-btn" id="tts-prev-btn" title="上一段">⏮</button><button class="tts-ctrl-btn tts-main-toggle" id="tts-toggle-btn" title="播放/暫停">▶</button><button class="tts-ctrl-btn" id="tts-next-btn" title="下一段">⏭</button><button class="tts-ctrl-btn" id="tts-stop-btn" title="停止">⏹</button></div><div class="tts-progress-container" id="tts-progress-bar"><div class="tts-progress-fill" id="tts-progress-fill" style="width:0%;"></div></div><div class="tts-settings"><div class="tts-speed-selector"><button class="tts-speed-btn" id="tts-speed-btn">1.0x</button><div class="tts-speed-dropdown tts-hidden" id="tts-speed-menu"><span data-rate="0.8">0.8x</span><span data-rate="1.0" class="active">1.0x</span><span data-rate="1.25">1.25x</span><span data-rate="1.5">1.5x</span><span data-rate="2.0">2.0x</span></div></div><select class="tts-voice-select" id="tts-voice-select" title="發音人選擇"></select><button class="tts-close-btn" id="tts-close-btn" title="收起播放面板">✕</button></div></div>`;document.body.appendChild(floating);this.floatingPlayerEl=floating;this.bindPlayerEvents();this.updateVoiceSelectOptions();}updateVoiceSelectOptions(){if(!this.floatingPlayerEl)return;const select=this.floatingPlayerEl.querySelector('#tts-voice-select');if(!select)return;select.innerHTML='';if(this.voices.length===0){const opt=document.createElement('option');opt.value='';opt.textContent='預設中文聲音';select.appendChild(opt);return;}this.voices.forEach((v,idx)=>{const opt=document.createElement('option');opt.value=idx;opt.textContent=`${v.name}(${v.lang})`;if(this.selectedVoice&&v.name===this.selectedVoice.name){opt.selected=true;}select.appendChild(opt);});}bindPlayerEvents(){if(!this.floatingPlayerEl)return;const toggleBtn=this.floatingPlayerEl.querySelector('#tts-toggle-btn');const prevBtn=this.floatingPlayerEl.querySelector('#tts-prev-btn');const nextBtn=this.floatingPlayerEl.querySelector('#tts-next-btn');const stopBtn=this.floatingPlayerEl.querySelector('#tts-stop-btn');const closeBtn=this.floatingPlayerEl.querySelector('#tts-close-btn');const progressBar=this.floatingPlayerEl.querySelector('#tts-progress-bar');const speedBtn=this.floatingPlayerEl.querySelector('#tts-speed-btn');const speedMenu=this.floatingPlayerEl.querySelector('#tts-speed-menu');const voiceSelect=this.floatingPlayerEl.querySelector('#tts-voice-select');toggleBtn.addEventListener('click',()=>{if(this.isPlaying){if(this.isPaused)this.resume();else this.pause();}else{this.playFrom(this.currentIndex);}});prevBtn.addEventListener('click',()=>{if(this.currentIndex>0){this.playFrom(this.currentIndex-1);}});nextBtn.addEventListener('click',()=>{if(this.currentIndex<this.chunks.length-1){this.playFrom(this.currentIndex+1);}});stopBtn.addEventListener('click',()=>this.stop());closeBtn.addEventListener('click',()=>this.hideFloatingPlayer());progressBar.addEventListener('click',(e)=>{const rect=progressBar.getBoundingClientRect();const clickX=e.clientX-rect.left;const ratio=Math.max(0,Math.min(1,clickX/rect.width));const targetIndex=Math.floor(ratio*this.chunks.length);this.playFrom(targetIndex);});speedBtn.addEventListener('click',(e)=>{e.stopPropagation();speedMenu.classList.toggle('tts-hidden');});document.addEventListener('click',()=>{if(speedMenu&&!speedMenu.classList.contains('tts-hidden')){speedMenu.classList.add('tts-hidden');}});speedMenu.querySelectorAll('span').forEach(item=>{item.addEventListener('click',(e)=>{e.stopPropagation();const rateVal=parseFloat(item.getAttribute('data-rate'));this.rate=rateVal;speedBtn.textContent=`${rateVal}x`;speedMenu.querySelectorAll('span').forEach(s=>s.classList.remove('active'));item.classList.add('active');speedMenu.classList.add('tts-hidden');if(this.isPlaying&&!this.isPaused){this.playFrom(this.currentIndex);}});});voiceSelect.addEventListener('change',(e)=>{const idx=parseInt(e.target.value);if(this.voices[idx]){this.selectedVoice=this.voices[idx];if(this.isPlaying&&!this.isPaused){this.playFrom(this.currentIndex);}}});}playFrom(index){if(!this.synth)return;if(index<0)index=0;if(index>=this.chunks.length){this.finish();return;}this.synth.cancel();this.currentIndex=index;this.isPlaying=true;this.isPaused=false;const chunk=this.chunks[index];const u=new SpeechSynthesisUtterance(chunk.text);u.rate=this.rate;if(this.selectedVoice){u.voice=this.selectedVoice;}u.onstart=()=>{this.updateUI();this.highlightChunk(chunk);};u.onend=()=>{this.clearHighlight();if(this.isPlaying&&!this.isPaused){this.playFrom(this.currentIndex+1);}};u.onerror=(err)=>{console.warn('TTS朗讀報錯:',err);this.clearHighlight();if(this.isPlaying&&this.currentIndex<this.chunks.length-1){setTimeout(()=>this.playFrom(this.currentIndex+1),200);}else{this.stop();}};this.utterance=u;this.synth.speak(u);this.showFloatingPlayer();this.updateUI();}pause(){if(!this.synth)return;if(this.isPlaying&&!this.isPaused){this.synth.pause();this.isPaused=true;this.updateUI();}}resume(){if(!this.synth)return;if(this.isPlaying&&this.isPaused){this.synth.resume();this.isPaused=false;this.updateUI();}else if(!this.isPlaying){this.playFrom(this.currentIndex);}}stop(){if(this.synth){this.synth.cancel();}this.isPlaying=false;this.isPaused=false;this.currentIndex=0;this.clearHighlight();this.updateUI();this.hideFloatingPlayer();}finish(){this.stop();const statusText=document.getElementById('tts-status-text');if(statusText)statusText.textContent='朗讀已完成';}highlightChunk(chunk){this.clearHighlight();if(chunk&&chunk.element){chunk.element.classList.add('tts-highlighting');chunk.element.scrollIntoView({behavior:'smooth',block:'center'});}}clearHighlight(){document.querySelectorAll('.tts-highlighting').forEach(el=>{el.classList.remove('tts-highlighting');});}updateUI(){if(!this.floatingPlayerEl)return;const toggleBtn=this.floatingPlayerEl.querySelector('#tts-toggle-btn');const statusText=this.floatingPlayerEl.querySelector('#tts-status-text');const progressFill=this.floatingPlayerEl.querySelector('#tts-progress-fill');const headerBtn=document.querySelector('#tts-start-btn.tts-text');const pct=Math.min(100,Math.round(((this.currentIndex+1)/this.chunks.length)*100));if(progressFill)progressFill.style.width=`${pct}%`;if(this.isPlaying&&!this.isPaused){if(toggleBtn)toggleBtn.textContent='⏸';if(statusText&&this.chunks[this.currentIndex]){const txt=this.chunks[this.currentIndex].text;statusText.textContent=`朗讀中(${pct}%):${txt.substring(0,18)}...`;}if(headerBtn)headerBtn.textContent='暫停朗讀';}else if(this.isPaused){if(toggleBtn)toggleBtn.textContent='▶';if(statusText)statusText.textContent=`已暫停(${pct}%)`;if(headerBtn)headerBtn.textContent='繼續朗讀';}else{if(toggleBtn)toggleBtn.textContent='▶';if(statusText)statusText.textContent='準備就緒';if(headerBtn)headerBtn.textContent='聽這篇文章';}}showFloatingPlayer(){if(this.floatingPlayerEl){this.floatingPlayerEl.classList.remove('tts-hidden');}}hideFloatingPlayer(){if(this.floatingPlayerEl){this.floatingPlayerEl.classList.add('tts-hidden');}}}const reader=new AudioReader();window.audioReader=reader;if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>reader.init());}else{reader.init();}})();

